fn render_section(
    &mut self,
    section: Section,
    window: &mut Window,
    cx: &mut Context<Self>,
) -> AnyElement {
    let theme = cx.theme().clone();
    let muted = theme.muted_foreground;
    let heading = self.render_heading(section, cx);
    let mut column = v_flex()
        .w_full()
        .gap(ROW_GAP)
        .track_focus(&self.section_focus[section.key()])
        .child(div().pb(HEADING_GAP - ROW_GAP).child(heading));
    // While the plan is read: skeleton rows, never an empty section.
    if !self.loaded && section != Section::Done {
        if section == Section::Next
            && let Some(why) = self.load_error.clone()
        {
            column = column.child(gpui_kit::TestSupportExt::test_support(
                h_flex()
                    .id("planning-load-error")
                    .gap_2()
                    .items_center()
                    .child(div().flex_1().text_sm().text_color(theme.danger).child(why))
                    .child(
                        Button::new("planning-load-retry")
                            .ghost()
                            .xsmall()
                            .label("Try again")
                            .tooltip("Read the plan again")
                            .on_click(cx.listener(|this, _, _, cx| this.read_again(cx))),
                    ),
            ));
        } else {
            column = column.child(gpui_kit::TestSupportExt::test_support(
                v_flex()
                    .id(SharedString::from(format!(
                        "planning-loading-{}",
                        section.key()
                    )))
                    .gap(ROW_GAP)
                    .child(skeleton_row(cx))
                    .child(skeleton_row(cx)),
            ));
        }
        return column.into_any_element();
    }
    let about = self.panel_about();
    let panel_wanted = self.drafting.is_some() || !self.proposals.is_empty();
    if section == Section::Backlog && panel_wanted && about.is_none() {
        // Proposals kept from before come back in their panel.
        if self.drafting.is_none() {
            self.open_draft_panel(None, false, window, cx);
        }
        column = column.child(self.render_draft_panel(window, cx));
    }
    if section == Section::Done && !self.done_expanded {
        return column.into_any_element();
    }
    let gap = self.gap.get();
    let count = self.sections[section_ix(section)].len();
    if count == 0 {
        // Lets UI tests find the empty state; inert in normal builds.
        column = column.child(gpui_kit::TestSupportExt::test_support(
            self.drop_zone(
                section,
                0,
                div().id(SharedString::from(format!(
                    "planning-empty-{}",
                    section.key()
                ))),
                cx,
            )
            .child(empty_line(section.empty(), muted)),
        ));
    }
    for ix in 0..count {
