/// The story `name`'s steps, a row each, in order, indented beneath it,
/// each with its own status once the story is sent; none while it has
/// none. Listed at `collapse`, they show only their count until it is
/// expanded.
fn render_story_steps(
    &self,
    name: &str,
    collapse: Option<String>,
    cx: &mut Context<Self>,
) -> Option<AnyElement> {
    let story = self.story(name)?;
    if story.steps().is_empty() {
        return None;
    }
    let theme = cx.theme().clone();
    let muted = theme.muted_foreground;
    let task = story.task.clone();
    let count = story.steps().len() + 1;
    let expanded = collapse
        .as_ref()
        .is_none_or(|key| self.steps_expanded.contains(key));
    let toggle = collapse.map(|key| {
        let id = SharedString::from(format!("planning-step-list-{key}"));
        h_flex()
            .id(id)
            .h(px(24.))
            .px_3()
            .gap_1()
            .items_center()
            .rounded(theme.radius)
            .cursor_pointer()
            .text_xs()
            .text_color(muted)
            .hover(|row| row.bg(theme.list_hover))
            .aria_label(if expanded { "Hide steps" } else { "Show steps" })
            .on_click(cx.listener(move |this, _, _, cx| {
                if !this.steps_expanded.remove(&key) {
                    this.steps_expanded.insert(key.clone());
                }
                cx.notify();
            }))
            .child(
                Icon::new(if expanded {
                    IconName::ChevronDown
                } else {
                    IconName::ChevronRight
                })
                .xsmall(),
            )
            .child(format!("{count} steps"))
    });
    let rows = story
        .steps()
        .iter()
        .enumerate()
        .filter(|_| expanded)
        .map(|(at, step)| {
            let status = task.as_deref().map(|task| {
                (self.hooks.step_state)(task, at, cx).unwrap_or((StoryState::Queued, None))
            });
            gpui_kit::TestSupportExt::test_support(
                h_flex()
                    .id(SharedString::from(format!("planning-sent-step-{name}-{at}")))
                    .w_full()
                    .h(ROW_HEIGHT)
                    .flex_none()
                    .px_3()
                    .gap_2()
                    .items_center()
                    .child(div().w(GRIP_WIDTH).flex_none())
                    .child(
                        div()
                            .w(PILL_WIDTH)
                            .flex_none()
                            .child(mode_pill_label(step.mode, cx)),
                    )
                    .child(
                        div()
                            .flex_none()
                            .text_xs()
                            .text_color(muted)
                            .child(format!("{}.", at + 2)),
                    )
                    .child(
                        div()
                            .flex_1()
                            .min_w_0()
                            .truncate()
                            .text_sm()
                            .text_color(muted)
                            .child(step.prompt.lines().next().unwrap_or_default().to_string()),
                    )
                    .child(
                        div()
                            .w(STATUS_WIDTH)
                            .flex_none()
                            .flex()
                            .justify_end()
                            .children(
                                status.map(|(state, elapsed)| status_label(state, elapsed, cx)),
                            ),
                    ),
            )
        })
        .collect::<Vec<_>>();
    Some(
        v_flex()
            .w_full()
            .pl(px(16.))
            .gap(ROW_GAP)
            .children(toggle)
            .children(rows)
            .into_any_element(),
    )
}

